#include "PermissionManager.h"
namespace vox {juce::Array<Permission>PermissionManager::permissions(Role r)const{using P=Permission;if(r==Role::SuperAdministrator)return{P::ViewLogs,P::ExportLogs,P::ManagePresets,P::CreateBackup,P::RestoreBackup,P::ManageUsers,P::ManagePermissions,P::ManageSecurity,P::ManageSettings,P::DeleteLogs};if(r==Role::Administrator)return{P::ViewLogs,P::ExportLogs,P::ManagePresets,P::CreateBackup,P::ManageUsers,P::ManagePermissions,P::ManageSettings};if(r==Role::Moderator)return{P::ViewLogs,P::ExportLogs,P::ManagePresets};return{};}bool PermissionManager::allowed(Role r,Permission p)const{return permissions(r).contains(p);}juce::String PermissionManager::name(Permission p){const char*names[]{"Visualizar logs","Exportar logs","Gerenciar presets","Criar backup","Restaurar backup","Gerenciar usuários","Gerenciar permissões","Gerenciar segurança","Configurações administrativas","Excluir logs"};return juce::String::fromUTF8(names[(int)p]);}}
